INSERT INTO providers.api_endpoints(id,api_id,path,method,price,active,description,query_params,response_body,response_example) SELECT '82d08ea7-bb11-40c0-890b-c20334f682b5',e.api_id,'/odata/v1/CBS/85809NED/Properties',e.method,e.price,true,'Publication date, source description and revision policy for construction turnover table 85809NED.',e.query_params - 'required' #- '{properties,tableId}','{"type": "object", "required": ["Identifier", "Title"], "properties": {}}'::jsonb,'{"@odata.context": "https://datasets.cbs.nl/odata/v1/CBS/85809NED/$metadata#Properties", "Identifier": "85809NED", "Title": "Bouwnijverheid; omzetontwikkeling, index 2021=100", "Description": "Deze tabel bevat cijfers over de omzetontwikkeling van de bouwnijverheid. De ontwikkeling wordt weergegeven als procentuele verandering ten opzichte van dezelfde periode in het voorafgaande jaar en door middel van indexcijfers met als basisjaar 2021. De gegevens kunnen worden uitgesplitst naar bedrijfsgrootte en branches volgens de Standaard Bedrijfsindeling 2008 (SBI 2008).\r\n\r\nGegevens beschikbaar vanaf januari 2005. \r\n\r\nStatus van de cijfers:\r\nDe cijfers over januari t/m juni 2026 zijn voorlopig en de overige perioden zijn definitief.\r\n\r\nWijzigingen per 20 augustus 2026:\r\nDe cijfers van juni en het tweede kwartaal van 2026 zijn toegevoegd en de cijfers van april en mei 2026 zijn eventueel bijgesteld.\r\n\r\nWanneer komen er nieuwe cijfers?\r\nDe voorlopige uitkomsten publiceert het CBS als regel binnen zes tot acht weken na afloop van de verslagmaand. Tot uiterlijk 75 dagen na afloop van een kwartaal kunnen de voorlopige cijfers wijzigen als gevolg van nagekomen informatie van respondenten. Daarna wijzigen de cijfers niet totdat, uiterlijk vijf maanden na afloop van het jaar, de laatste nagekomen informatie wordt verwerkt. Daarna zijn alle verslagmaanden van dat jaar ''definitief''. Tot die tijd wordt de status ''voorlopig'' aangehouden voor de uitkomsten.\r\n\r\nNa publicatie van definitieve uitkomsten past het CBS de uitkomsten alleen aan als er grote bijstellingen en/of correcties noodzakelijk zijn.\r\n\r\n\r\n", "Language": "nl", "Authority": "https://standaarden.overheid.nl/owms/terms/Centraal_Bureau_voor_de_Statistiek", "Modified": "2026-08-20T00:00:00+02:00", "ReleaseDate": "2026-08-20T00:00:00+02:00", "ModificationDate": "2026-08-20T00:00:00+02:00", "TemporalCoverage": "2005 - 2025, 2005 KW I - 2026 KW II. jan. 2005 - juni 2026", "Catalog": "CBS", "Publisher": "https://standaarden.overheid.nl/owms/terms/Centraal_Bureau_voor_de_Statistiek", "ContactPoint": "infoservice@cbs.nl", "Version": "202608200000", "VersionNotes": "", "VersionReason": "Actualisering", "Frequency": "Per maand", "Status": "Regulier", "ObservationCount": 19824, "ObservationsModified": "2026-08-20T00:00:00+02:00", "DatasetType": "Numeric", "GraphTypes": "Table,Bar,Line", "License": "https://creativecommons.org/licenses/by/4.0/", "Source": "CBS.", "Summary": "Bouwnijverheid. Omzet: indexcijfers 2021=100, ontwikkeling.\nNaar activiteit en omvang (vanaf 1, vanaf 10 en meer werkzame personen)", "LongDescription": "INHOUDSOPGAVE\r\n\r\n1. Toelichting\r\n2. Definities en verklaring van symbolen\r\n3. Koppelingen naar relevante tabellen en artikelen\r\n4. Bronnen en methoden\r\n5. Meer informatie\r\n\r\n\r\n1. TOELICHTING\r\n\r\nDeze tabel bevat cijfers over de omzetontwikkeling van de bouwnijverheid. De ontwikkeling wordt weergegeven als procentuele verandering ten opzichte van dezelfde periode in het voorafgaande jaar en door middel van indexcijfers met als basisjaar 2021. De gegevens kunnen worden uitgesplitst naar bedrijfsgrootte en branches volgens de Standaard Bedrijfsindeling 2008 (SBI 2008).\r\n\r\nGegevens beschikbaar vanaf januari 2005. \r\n\r\nStatus van de cijfers:\r\nDe cijfers over januari t/m juni 2026 zijn voorlopig en de overige perioden zijn definitief.\r\n\r\nWijzigingen per 20 augustus 2026:\r\nDe cijfers van juni en het tweede kwartaal van 2026 zijn toegevoegd en de cijfers van april en mei 2026 zijn eventueel bijgesteld.\r\n\r\nWanneer komen er nieuwe cijfers?\r\nDe voorlopige uitkomsten publiceert het CBS als regel binnen zes tot acht weken na afloop van de verslagmaand. Tot uiterlijk 75 dagen na afloop van een kwartaal kunnen de voorlopige cijfers wijzigen als gevolg van nagekomen informatie van respondenten. Daarna wijzigen de cijfers niet totdat, uiterlijk vijf maanden na afloop van het jaar, de laatste nagekomen informatie wordt verwerkt. Daarna zijn alle verslagmaanden van dat jaar ''definitief''. Tot die tijd wordt de status ''voorlopig'' aangehouden voor de uitkomsten.\r\n\r\nNa publicatie van definitieve uitkomsten past het CBS de uitkomsten alleen aan als er grote bijstellingen en/of correcties noodzakelijk zijn.\r\n\r\n\r\n2. DEFINITIES EN VERKLARING VAN SYMBOLEN\r\n\r\nDefinities:\r\n\r\nOmzet\r\nDe opbrengst uit verkoop van goederen en diensten aan derden, exclusief btw. De omzet omvat zowel de opbrengst uit hoofdactiviteit als uit nevenactiviteiten. Derden zijn consumenten en bedrijven buiten het (Nederlandse deel van het) eigen concernverband.\r\n\r\nIndexcijfer \r\nGeeft de verhouding weer tussen de waarde van een bepaalde variabele (bijv. omzet) in een bepaalde periode en de waarde van diezelfde variabele in de basisperiode. Deze basisperiode heeft het indexcijfer 100.\r\n\r\nOntwikkeling\r\nDe procentuele ontwikkeling van een bepaalde periode (maand, kwartaal, jaar) ten opzichte van dezelfde periode in het daaraan voorafgaande jaar. Het CBS berekent de ontwikkeling aan de hand van niet-afgeronde indexcijfers. \r\n\r\nBedrijfsgrootte (werkzame personen)\r\nHet aantal werkzame personen bij een bedrijf is het aantal werknemers op de eigen loonlijst, verminderd met het uitgeleende personeel en vermeerderd met het ingeleend personeel, ingehuurde uitzendkrachten/gedetacheerden en overige werkzame personen zoals medewerkende eigenaren en vennoten.\r\n\r\nStandaard Bedrijfsindeling 2008 (SBI 2008):\r\nDe Nederlandse hiërarchische indeling van economische activiteiten die door het CBS wordt gebruikt om bedrijfseenheden in te delen naar hun hoofdactiviteit. De SBI 2008 is de versie die vanaf 2008 gebruikt wordt.\r\n“Bedrijfstak” of “branche” zijn gangbare termen voor groepen van bedrijven met dezelfde hoofdactiviteit. Het CBS hanteert voor de indeling van bedrijven naar hoofdactiviteit de zogenoemde Standaard Bedrijfsindeling (SBI). Bedrijven in een bedrijfstak of branche kunnen naast deze activiteit ook andere activiteiten (nevenactiviteiten) uitoefenen. De SBI 2008 kent meerdere niveaus die aangegeven worden door maximaal vijf cijfers. Het niveau van vier cijfers komt vrijwel overeen met de indeling van de Europese Unie (NACE). De eerste twee cijfers komen overeen met die van de indeling van Verenigde Naties (ISIC).\r\n\r\nVerklaring van symbolen:\r\n\r\nniets (blanco) : het cijfer kan op logische gronden niet voorkomen\r\n. : het cijfer is onbekend, onvoldoende betrouwbaar of geheim\r\n* : voorlopige cijfers\r\n** : nader voorlopige cijfers\r\n\r\n\r\n3. KOPPELINGEN NAAR RELEVANTE TABELLEN EN ARTIKELEN\r\n\r\nRelevante tabellen:\r\n\r\nMaandcijfers over de volume-ontwikkeling van de toegevoegde waarde in basisprijzen van de bouwnijverheid zijn te vinden in de tabel:\r\n<a href=''https://opendata.cbs.nl/statline/#/CBS/nl/dataset/85808NED/table?ts=1712728004819''>Bouwnijverheid; toegevoegde waarde in basisprijzen, volume-index 2021.</a>\r\n\r\nJaarcijfers voor de bedrijfstak bouwnijverheid met uitkomsten over werkgelegenheid en winst- en verliesrekening zijn te vinden in de tabel\r\n<a href=''https://opendata.cbs.nl/statline/#/CBS/nl/dataset/81156NED''>Bedrijfsleven; arbeids- en financiële gegevens, per branche, SBI 2008</a>.\r\n\r\nRelevante artikelen:\r\n\r\nMeer informatie is te vinden op de themapagina <a href=''https://www.cbs.nl/nl-nl/economie/bouwen-en-wonen''>Bouwen en wonen.</a>\r\n\r\n\r\n4. BRONNEN EN METHODEN\r\n\r\nEr is een basisverlegging doorgevoerd. Meer informatie over deze basisverlegging is te vinden in het document <a href=''https://www.cbs.nl/nl-nl/onze-diensten/methoden/onderzoeksomschrijvingen/aanvullende-onderzoeksomschrijvingen/basisverlegging-omzet-en-prijzenstatistieken-2024''>Basisverlegging omzet- en prijzenstatistieken 2024.</a>\r\n\r\nDe onderzoeksmethode van deze tabel is te vinden in de <a href=''https://www.cbs.nl/nl-nl/onze-diensten/methoden/onderzoeksomschrijvingen/korte-onderzoeksbeschrijvingen/omzetontwikkeling ''>onderzoeksbeschrijving Omzetontwikkeling.</a>\r\n\r\nVoor informatie over de Standaard Bedrijfsindeling zie <a href=''https://www.cbs.nl/nl-nl/onze-diensten/methoden/classificaties/activiteiten/sbi-2008-standaard-bedrijfsindeling-2008 ''>SBI 2008- Standaard Bedrijfsindeling 2008</a>.\r\n\r\n\r\n5. MEER INFORMATIE\r\n\r\n<a href=''https://www.cbs.nl/nl-nl/over-ons/contact/infoservice''>Infoservice</a>\r\n\r\nCopyright © Centraal Bureau voor de Statistiek, Den Haag/Heerlen\r\n\r\nVerveelvoudiging is toegestaan, mits het CBS als bron wordt vermeld.\r\n\r\n", "Provenance": [{"Title": "Basisverlegging omzet- en prijzenstatistieken 2024.", "Url": "https://www.cbs.nl/nl-nl/onze-diensten/methoden/onderzoeksomschrijvingen/aanvullende-onderzoeksomschrijvingen/basisverlegging-omzet-en-prijzenstatistieken-2024"}, {"Title": "onderzoeksbeschrijving Omzetontwikkeling.", "Url": "https://www.cbs.nl/nl-nl/onze-diensten/methoden/onderzoeksomschrijvingen/korte-onderzoeksbeschrijvingen/omzetontwikkeling"}, {"Title": "SBI 2008- Standaard Bedrijfsindeling 2008", "Url": "https://www.cbs.nl/nl-nl/onze-diensten/methoden/classificaties/activiteiten/sbi-2008-standaard-bedrijfsindeling-2008"}], "RelatedSources": [{"Title": "Bouwnijverheid; toegevoegde waarde in basisprijzen, volume-index 2021.", "Url": "https://opendata.cbs.nl/statline/#/CBS/nl/dataset/85808NED/table?ts=1712728004819"}, {"Title": "Bedrijfsleven; arbeids- en financiële gegevens, per branche, SBI 2008", "Url": "https://opendata.cbs.nl/statline/#/CBS/nl/dataset/81156NED"}, {"Title": "Bouwen en wonen.", "Url": "https://www.cbs.nl/nl-nl/economie/bouwen-en-wonen"}], "Distributions": [{"Format": "csv", "MediaType": "csv", "DownloadUrl": "https://datasets.cbs.nl/csv/CBS/nl/85809NED", "AccessUrl": "https://dataportal.cbs.nl/detail/CBS/85809NED", "Language": "nl"}, {"Format": "odata", "MediaType": "odata", "DownloadUrl": "https://datasets.cbs.nl/odata/v1/CBS/85809NED", "AccessUrl": "https://dataportal.cbs.nl/detail/CBS/85809NED", "Language": "nl"}]}'::jsonb FROM providers.api_endpoints e JOIN providers.apis a ON a.id=e.api_id WHERE a.slug='cbs-statline' AND e.path='/odata/v1/CBS/{tableId}/MeasureCodes' AND e.active ON CONFLICT(id) DO NOTHING;
